const body = $input.first().json.body || {};
const topic = String(body.topic || '').trim();
const notes = String(body.notes || '').trim();
const reasons = [];

if (!topic) reasons.push('topic is required');
if (topic.length > 200) reasons.push('topic longer than 200 characters');
if (notes.length > 1000) reasons.push('notes longer than 1000 characters');

// Treat all sheet/webhook text as untrusted: block obvious instruction-hijack phrases.
const injection = [
  /ignore\s+(all\s+|any\s+|the\s+)?(previous|prior|above)\s+instructions/i,
  /disregard\s+(all\s+|any\s+|the\s+)?(previous|prior|above)/i,
  /new\s+instructions?:/i,
  /<\/?(system|assistant|user)>/i,
];
if (injection.some(p => p.test(topic + ' ' + notes))) reasons.push('possible prompt injection');

return [{ json: { topic, notes, flagged: reasons.length > 0, reasons } }];

const input = $('Validate input').first().json;
const raw = $input.first().json.choices[0].message.content;

let draft;
try { draft = JSON.parse(raw); }
catch (e) { return [{ json: { status: 'Error', error: 'model did not return valid JSON' } }]; }

const caption = String(draft.caption || '');
const slides = Array.isArray(draft.slides) ? draft.slides.map(String) : [];
const script = String(draft.script || '');

// Compliance is code, not a prompt: banned profit-promise language.
const banned = [
  /\bguaranteed?\b/i, /\brisk[- ]free\b/i, /\bno risk\b/i, /\bcan'?t lose\b/i,
  /\bget rich\b/i, /\bdouble your money\b/i, /\bsure profit\b/i, /\beasy money\b/i,
  /\b100% win\b/i, /\bmake \$\d[\d,]* (a|per) (day|week|month)\b/i,
];
const all = [caption, ...slides, script].join(' ');
const flags = banned.filter(p => p.test(all)).map(p => 'banned phrase: ' + p.source);

const words = script.trim().split(/\s+/).filter(Boolean).length;
if (caption.length > 2200) flags.push('caption longer than 2200 characters');
if (slides.length < 5 || slides.length > 8) flags.push('carousel must have 5-8 slides, got ' + slides.length);
if (words < 80 || words > 200) flags.push('script must be 80-200 words, got ' + words);

if (flags.length) {
  return [{ json: { status: 'Flagged', topic: input.topic, flags } }];
}

const D = ' [ADD RISK DISCLAIMER]';
slides[slides.length - 1] += D;
return [{ json: {
  status: 'Drafted', topic: input.topic, flags: [],
  caption: caption + D,
  carousel_outline: slides.map((s, i) => (i + 1) + '. ' + s).join('\n'),
  video_script: script + D,
} }];
